/* WEJDAN FIT — privacy-first, local-only fitness companion.
   Source: user's WEJDAN FIT V6; identity tokens: user's Figma Wejdan — Color.
   No backend, account, telemetry, AI API, or automatic calorie claims. */
(()=>{
'use strict';
const DATA=window.FIT_DATA||{exercises:[],recipes:[],progression:[],mealIdeas:[],sources:[]};
const KEY='wejdan-fit-app-v1';
const BASE={version:1,settings:{startDate:'2026-11-23',startWeight:0,targetWeight:0,height:0,age:0,setupComplete:false,activity:'قليل جدًا',goalHigh:1650,goalMedium:1500,protein:100,carbHigh:200,carbMedium:140,fatHigh:50,fatMedium:60,trainingSets:1,theme:'light'},weights:[],meals:[],habits:{},workouts:{},foodModes:{},feelings:{}};
const deep=x=>JSON.parse(JSON.stringify(x));
function parseSaved(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(!raw||typeof raw!=='object')return deep(BASE);return {...deep(BASE),...raw,settings:{...deep(BASE.settings),...(raw.settings||{})},weights:Array.isArray(raw.weights)?raw.weights:[],meals:Array.isArray(raw.meals)?raw.meals:[],habits:raw.habits&&typeof raw.habits==='object'?raw.habits:{},workouts:raw.workouts&&typeof raw.workouts==='object'?raw.workouts:{},foodModes:raw.foodModes&&typeof raw.foodModes==='object'?raw.foodModes:{},feelings:raw.feelings&&typeof raw.feelings==='object'?raw.feelings:{}}}catch(e){return deep(BASE)}}
let deferredInstallPrompt=null;
let state=parseSaved();let view='home',selectedSession='A',recipeSearch='',recipeCategory='الكل',recipeSelected=null,restSeconds=60,restInterval=null,toastTimer=null,modalId=null,weekManual=null;
const NAV=[['home','اليوم','home'],['workout','تماريني','dumbbell'],['food','أكلي','utensils'],['progress','تقدّمي','chart'],['more','المزيد','sparkles']];
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',dumbbell:'<path d="m6.5 6.5 11 11M3 10l7-7M14 21l7-7M5 12l7-7M12 19l7-7"/>',utensils:'<path d="M4 3v8a4 4 0 0 0 8 0V3M8 3v18M19 3v18M19 3c-3 2-3 8 0 9"/>',chart:'<path d="M3 3v18h18M6 16l5-5 4 3 5-8"/>',sparkles:'<path d="m12 3 1.6 5.4L19 10l-5.4 1.6L12 17l-1.6-5.4L5 10l5.4-1.6zM19 17l.8 2.2L22 20l-2.2.8L19 23l-.8-2.2L16 20l2.2-.8z"/>',moon:'<path d="M20 14.2A8 8 0 0 1 9.8 4 8.4 8.4 0 1 0 20 14.2Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4m0-14.2-1.4 1.4M6.3 17.7l-1.4 1.4"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 1 0-7.8 7.8L12 20.4l8.8-8.9a5.5 5.5 0 0 0 0-7.8z"/>',check:'<path d="m4 12 5 5L20 6"/>',weight:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M9 11a3 3 0 0 1 6 0m-3 0v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4m8-4v4M3 10h18"/>',play:'<path d="m8 5 12 7-12 7z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m7 14-2 8 7-3 7 3-2-8"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m6 20 3-6 3 2 2 6m-5-8 2-5 4 2 2 4m-6-8-3 4"/>',sleep:'<path d="M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15Z"/>',add:'<path d="M12 5v14M5 12h14"/>',trash:'<path d="M3 6h18M8 6V4h8v2m-9 0 1 15h8l1-15M10 10v7m4-7v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M5 17v4h14v-4"/>',warning:'<path d="m12 3 10 18H2zM12 9v5m0 3v.3"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',coffee:'<path d="M3 8h14v7a7 7 0 0 1-14 0zM17 9h2a3 3 0 1 1 0 6h-2M2 21h18"/>'};
const I=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.sparkles}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Number.isFinite(Number(x))?Number(x):0;
const fmt=(x,dp=0)=>Number(x||0).toLocaleString('ar-SA',{maximumFractionDigits:dp,minimumFractionDigits:0});
function iso(d=new Date()){let z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)}
const today=()=>iso();
const prettyDate=(d)=>new Date(d+'T12:00:00').toLocaleDateString('ar-SA',{weekday:'long',day:'numeric',month:'long'});
function dayOffset(s,days){const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+days);return iso(d)}
function weekIndex(d=today()){const start=new Date(state.settings.startDate+'T12:00:00'),target=new Date(d+'T12:00:00');return Math.min(26,Math.max(1,Math.floor((target-start)/(86400000*7))+1))}
function updateSaveIndicator(success=true){const el=document.getElementById('saveIndicator');if(!el)return;el.classList.toggle('is-saved',success);el.classList.toggle('is-error',!success);el.textContent=success?'✓ محفوظ على هذا الجهاز':'تعذّر الحفظ المحلي'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));updateSaveIndicator(true);return true}catch(e){updateSaveIndicator(false);toast('تعذر الحفظ في هذا المتصفح. جرّبي Safari/Chrome العادي وتحققي من مساحة التخزين.');return false}}
function snackOfDay(){const lines=['اليوم ما نحتاج الكمال؛ نحتاج خطوة تشبه طاقتك.','التقدم يُبنى من الأيام العادية، مو من الأيام المثالية.','حتى لو كان إنجازك صغير، فهو إنجاز حقيقي.','الراحة جزء من التدريب، مو عكسه.','ما فيه تأخر. عندك إيقاعك الخاص.','قوّتك مو بس في العدّات؛ في إنك ترجعين بلطف.','كل يوم فرصة جديدة، بدون دين من أمس.','اسمحي لنفسك تنجحين بهدوء.','الإجابة مو دائمًا «أكثر»؛ أحيانًا «أذكى».'];return lines[Math.floor(new Date(today()+'T12:00:00').getTime()/86400000)%lines.length]}
function foodType(d=today()){if(state.foodModes[d])return state.foodModes[d];const day=new Date(d+'T12:00:00').getDay();return [1,3,5].includes(day)?'high':'medium'}
function targets(d=today()){const high=foodType(d)==='high';return {type:high?'أعلى كارب':'متوسط كارب',cal:high?n(state.settings.goalHigh):n(state.settings.goalMedium),p:n(state.settings.protein),c:high?n(state.settings.carbHigh):n(state.settings.carbMedium),f:high?n(state.settings.fatHigh):n(state.settings.fatMedium)}}
function todayMeals(d=today()){return state.meals.filter(x=>x.date===d)}
function nutrientTotal(d=today()){return todayMeals(d).reduce((a,x)=>{['cal','protein','carbs','fat'].forEach(k=>a[k]+=n(x[k]));return a},{cal:0,protein:0,carbs:0,fat:0})}
function workoutKey(d=today(),s=selectedSession){return d+'__'+s}
function workoutState(d=today(),s=selectedSession){return state.workouts[workoutKey(d,s)]||{sets:{},finished:false}}
function workoutFinished(){return Object.values(state.workouts).filter(x=>x.finished).length}
function lastWeight(){const weights=state.weights.filter(x=>Number.isFinite(Number(x.kg))).sort((a,b)=>a.date.localeCompare(b.date));return weights.length?n(weights[weights.length-1].kg):n(state.settings.startWeight)}
function progressPct(){const goal=n(state.settings.startWeight)-n(state.settings.targetWeight);return goal<=0?0:Math.max(0,Math.min(100,((n(state.settings.startWeight)-lastWeight())/goal)*100))}
function activityDates(){const set=new Set();state.weights.forEach(x=>set.add(x.date));state.meals.forEach(x=>set.add(x.date));Object.keys(state.habits).forEach(d=>{const h=state.habits[d];if(h&&(n(h.walk)>0||n(h.sleep)>0||n(h.water)>0))set.add(d)});Object.entries(state.workouts).forEach(([k,w])=>{if(w.finished)set.add(k.slice(0,10))});return set}
function activeWeekDays(){const days=activityDates();return Array.from({length:7},(_,i)=>dayOffset(today(),-i)).filter(d=>days.has(d)).length}
function rewards(){const workouts=workoutFinished(),act=activityDates().size,meals=state.meals.length,walks=Object.values(state.habits).filter(h=>n(h.walk)>0).length,loss=Math.max(0,n(state.settings.startWeight)-lastWeight());return [{icon:'✦',name:'أول خطوة',description:'سجّلتِ أول نشاط',ok:act>=1},{icon:'◈',name:'يوم المقاومة الأول',description:'أنهيتِ أول حصة',ok:workouts>=1},{icon:'✿',name:'أنا أعتني بنفسي',description:'3 أيام متابعة، بأي ترتيب',ok:act>=3},{icon:'✳',name:'خمس حصص بقوّة',description:'خمس حصص مقاومة مكتملة',ok:workouts>=5},{icon:'☾',name:'خطوات لطيفة',description:'3 أيام مشي مسجّلة',ok:walks>=3},{icon:'♡',name:'علاقتي بأكلي',description:'سجّلتِ 5 وجبات',ok:meals>=5},{icon:'❋',name:'تغير صغير',description:'نزول 1 كجم من خط البداية',ok:loss>=1},{icon:'✧',name:'استمراريتي',description:'10 أيام سجلات دون شرط التتابع',ok:act>=10}]}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
function confetti(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.getElementById('celebration');box.innerHTML='';for(let i=0;i<30;i++){const p=document.createElement('i');p.className='petal';p.style.left=(Math.random()*100)+'%';p.style.animationDelay=(Math.random()*.8)+'s';p.style.background=['#6172B5','#9BC4EE','#BEDAF7','#207F4D'][i%4];box.append(p)}setTimeout(()=>box.innerHTML='',3400)}
function pageHeader(title,subtitle,eyebrow='WEJDAN FIT'){return `<section class="page-header"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="date-pill">${esc(prettyDate(today()))}</div></section>`}
function navRender(){const side=document.getElementById('sideNav'),bottom=document.getElementById('bottomNav');side.innerHTML=NAV.map(([id,label,icon])=>`<button class="nav-link ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${I(icon)}${label}</button>`).join('');bottom.innerHTML=NAV.map(([id,label,icon])=>`<button class="bottom-link ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${I(icon)}<span>${label}</span></button>`).join('')}
function render(restore=false){const sc=window.scrollY;document.documentElement.dataset.theme=state.settings.theme==='dark'?'dark':'light';navRender();document.getElementById('themeSwitch').innerHTML=I(state.settings.theme==='dark'?'sun':'moon');document.querySelector('meta[name="theme-color"]').content=state.settings.theme==='dark'?'#0E121C':'#6172B5';const root=document.getElementById('app');root.innerHTML=({home:homeView,workout:workoutView,food:foodView,progress:progressView,more:moreView}[view]||homeView)();if(restore)window.scrollTo(0,sc)}
function navigate(to){if(!NAV.some(x=>x[0]===to))return;view=to;closeModal();render();window.scrollTo({top:0,behavior:'smooth'})}
function homeView(){const weight=lastWeight(),remaining=Math.max(0,weight-n(state.settings.targetWeight)),loss=Math.max(0,n(state.settings.startWeight)-weight),tw=targets(),daily=nutrientTotal(),hab=state.habits[today()]||{},wcount=workoutFinished(),aw=activeWeekDays(),date=today(),dow=new Date(date+'T12:00:00').getDay(),suggest=dow===1?'A':dow===4?'B':null,hasWorkout=Object.entries(state.workouts).some(([k,x])=>k.startsWith(date)&&x.finished),hasMeals=todayMeals().length>0,hasWalk=n(hab.walk)>0,acted=hasWorkout||hasMeals||hasWalk;return `
${pageHeader('أهلًا بكِ في مساحتك ✳','هنا نحتفل بخطواتك الصغيرة، ونخلي المشوار أخف عليكِ.','ONE DAY AT A TIME')}
<section class="hero card"><div class="hero-content"><div class="eyebrow">رسالتك اليوم · DAY ${Math.max(1,Math.floor((new Date(date+'T12:00:00')-new Date(state.settings.startDate+'T12:00:00'))/86400000)+1)}</div><h2>${acted?'أنتِ تسوينها، بطريقتك!':'بداية صغيرة. فرق كبير.'}</h2><p>${esc(snackOfDay())}</p><span class="hero-tag">♡ مو لازم يكون اليوم مثالي</span></div><div class="hero-art" aria-hidden="true">w<i>✷</i></div></section>
<section class="grid four" style="margin-top:19px"><article class="card kpi"><div class="kpi-icon">${I('weight')}</div><div class="label">وزنك المرجعي الحالي</div><div class="big"><span class="num">${fmt(weight,1)}</span> <small>كجم</small></div><div class="subtle">الهدف ${fmt(state.settings.targetWeight)} كجم</div></article><article class="card kpi"><div class="kpi-icon">${I('chart')}</div><div class="label">المتبقي لهدفك</div><div class="big"><span class="num">${fmt(remaining,1)}</span> <small>كجم</small></div><div class="progress"><i style="width:${progressPct().toFixed(1)}%"></i></div><div class="subtle" style="margin-top:7px">${fmt(progressPct(),1)}% من طريقك</div></article><article class="card kpi"><div class="kpi-icon">${I('dumbbell')}</div><div class="label">حصص المقاومة المنجزة</div><div class="big">${fmt(wcount)} <small>حصة</small></div><div class="subtle">ما فيه تعويض للأيام الفائتة</div></article><article class="card kpi"><div class="kpi-icon">${I('heart')}</div><div class="label">أيام اهتمامك بنفسك</div><div class="big">${fmt(aw)} <small>من 7</small></div><div class="subtle">مو لازم تكون متتالية</div></article></section>
<section class="grid two" style="margin-top:19px;align-items:start"><article class="card"><div class="card-header"><h2>ثلاث خطوات تكفي اليوم ♡</h2><span class="tag">على قد طاقتك</span></div><div class="task-list"><div class="task ${hasMeals?'done':''}"><div class="task-box">${hasMeals?I('check'):I('utensils')}</div><div class="task-main"><strong>تابعي وجباتك المعتادة</strong><span>وجبتان أو حسب جوعك، بدون حرمان</span></div><button class="task-action" data-view="food">${hasMeals?'تم ✓':'سجّلي'}</button></div><div class="task ${hasWalk?'done':''}"><div class="task-box">${hasWalk?I('check'):I('walk')}</div><div class="task-main"><strong>سجّلي حركتك أو راحتك</strong><span>الحركة المسموح بها طبيًا، أو يوم تعافٍ</span></div><button class="task-action" data-action="open-habit">${hasWalk?'تعديل':'تسجيل'}</button></div><div class="task ${hasWorkout?'done':''}"><div class="task-box">${hasWorkout?I('check'):I('dumbbell')}</div><div class="task-main"><strong>${suggest?'جلسة '+suggest+' إذا كانت مناسبة اليوم':'المقاومة حسب جدولك وتعافيك'}</strong><span>المهم جودة الحركة، مو عدد الأيام</span></div><button class="task-action" data-view="workout">${hasWorkout?'أنجزتِ ✓':'الخطة'}</button></div></div><div class="soft-rule"></div><div class="metric-row"><span class="subtle">ملاحظة</span><strong>كل يوم جديد يبدأ بصفر ديون!</strong></div></article>
<article class="card"><div class="card-header"><h2>تغذيتك اليوم</h2><span class="tag outline">هدف تجريبي</span></div><div class="metric-row"><div><span class="stat-label">المسجّل</span><div style="font-size:28px;font-weight:900"><span class="num">${fmt(daily.cal)}</span> <small style="font-size:12px;color:var(--muted)">سعرة</small></div></div><div style="text-align:left"><span class="stat-label">مثال ${tw.type}</span><div style="font-size:22px;font-weight:900"><span class="num">${fmt(tw.cal)}</span></div></div></div><div class="progress" style="margin:12px 0"><i style="width:${Math.min(100,tw.cal?daily.cal/tw.cal*100:0)}%"></i></div><div class="metric-row"><span class="subtle">بروتين مسجّل</span><strong>${fmt(daily.protein,1)} / ${fmt(tw.p)} جم</strong></div><div class="soft-rule"></div><div class="actions-row"><button class="btn secondary small" data-view="food">سجّلي وجبتك ${I('add')}</button><span class="subtle">التقدير لا يساوي قياسًا فعليًا</span></div></article></section>
<section class="grid two" style="margin-top:19px"><article class="quote-card"><div class="quote-caption">THE GENTLE REMINDER</div><blockquote>لا تقيسين نجاح يومك بكم تعبتِ فيه. قيسيه بكم اعتنيتِ بنفسك.</blockquote></article><article class="card"><div class="card-header"><h2>أوسمتك الجميلة</h2><button class="btn-plain" data-view="progress">كل الإنجازات</button></div><div class="badge-grid">${rewards().slice(0,4).map(r=>`<div class="achievement ${r.ok?'':'off'}"><div class="medal">${r.icon}</div><div><strong>${r.name}</strong><small>${r.ok?'مفتوح ✨':r.description}</small></div></div>`).join('')}</div></article></section>`}
function workoutView(){const w=weekIndex(),pro=DATA.progression.find(x=>n(x.week)===w)||DATA.progression[0]||{},exs=DATA.exercises.filter(x=>x.session===selectedSession),entry=workoutState(),doneCount=exs.reduce((sum,x)=>sum+(entry.sets?.[x.id]||[]).filter(Boolean).length,0),sets=Math.max(1,Math.min(3,n(state.settings.trainingSets))),max=exs.length*sets,finished=entry.finished;return `${pageHeader('تمارينك، خطوة بخطوة','جلسات مقاومة خفيفة: الأولوية لتحكمك بالحركة وراحة رقبتك وظهرك.','STRONG, SOFTLY')}
<div class="alert warn" style="margin-bottom:17px">${I('info')}<div>بناء على سماح الطبيبة الذي أخبرتِنا به. **تعليماتها لأي حركة أو وزن مقدّمة على التطبيق**. لا تنفّذي حركة تزيد الألم أو التنميل أو الضعف أو تغيّر لون/حرارة القدم. إذا ظهرت أعراض مفاجئة وشديدة، اطلبي الرعاية الطارئة.</div></div>
<section class="grid two"><article class="card"><div class="card-header"><h2>برنامج البداية · أسبوع ${fmt(w)} من 26</h2><span class="tag good">مبتدئة</span></div><p class="muted" style="margin-top:0">${esc(pro.allocation||'جلستان A وB غير متتاليتين؛ التقدم حسب التعافي')}</p><div class="week-timeline">${[1,2,3,4,5,6,7,8].map(k=>`<i class="week-dot ${w>=k?'active':''}"></i>`).join('')}</div><div class="metric-row"><span class="subtle">مرجع الأسبوع</span><strong>${esc(pro.sessions||'2')} جلسة</strong></div><div class="metric-row"><span class="subtle">المجموعات</span><strong>${esc(pro.sets||'1')}</strong></div><div class="metric-row"><span class="subtle">شعور الجهد RPE</span><strong>${esc(pro.rpe||'خفيف')}</strong></div><p class="subtle" style="margin:15px 0 0">التدرج لا يزيد تلقائيًا. اختاري عدد المجموعات الذي تسمح به الطبيبة ويتحمله جسمك.</p></article>
<article class="card"><div class="card-header"><h2>المقاومة المناسبة لكِ</h2><span class="tag">20–25 دقيقة تقريبًا</span></div><div class="pills" style="margin-bottom:15px"><button class="pill ${selectedSession==='A'?'active':''}" data-session="A">جلسة A · الجسم كامل</button><button class="pill ${selectedSession==='B'?'active':''}" data-session="B">جلسة B · تنويع</button></div><div class="form-row"><label class="field">مجموعات مريحة حاليًا<select id="setLevel"><option value="1" ${sets===1?'selected':''}>مجموعة واحدة</option><option value="2" ${sets===2?'selected':''}>مجموعتان عند الاستعداد</option><option value="3" ${sets===3?'selected':''}>3 مجموعات بعد التدرج والموافقة</option></select></label></div><div class="soft-rule"></div><div class="metric-row"><span class="subtle">المنجز في هذه الجلسة</span><strong>${fmt(doneCount)} / ${fmt(max)} مجموعات</strong></div><div class="progress" style="margin-top:8px"><i style="width:${max?doneCount/max*100:0}%"></i></div></article></section>
<section class="card" style="margin-top:18px"><div class="card-header"><div><h2>جلسة ${selectedSession} · تمارين اليوم</h2><span class="card-sub">3–5 دقائق إحماء لطيف، ثم حركة بطيئة ومتحكَّم فيها</span></div><span class="tag ${finished?'good':''}">${finished?'مكتملة ✓':'حصة مرنة'}</span></div>
${exs.map((x,i)=>{const checks=entry.sets?.[x.id]||[];return `<article class="exercise-row"><div class="exercise-number">${x.id}</div><div class="exercise-info"><h3>${esc(x.name)}</h3><p>${esc(x.muscle)} • ${esc(x.equipment||'بدون أدوات')}</p><div class="pills" style="margin-bottom:9px"><span class="tag outline">${esc(x.reps)} تكرار</span><span class="tag outline">${esc(x.rest)} راحة</span></div><div class="exercise-controls">${Array.from({length:sets},(_,j)=>`<button class="set-check ${checks[j]?'checked':''}" data-action="toggle-set" data-exercise="${x.id}" data-set="${j}" aria-pressed="${checks[j]?'true':'false'}">${checks[j]?'✓ ':''}المجموعة ${j+1}</button>`).join('')}<button class="btn-plain" data-action="exercise-details" data-exercise="${x.id}">الشرح + فيديو ${I('play')}</button></div></div></article>`}).join('')}
<div class="timer-box"><div><strong style="display:block">مؤقت راحة اختياري</strong><span class="subtle">استريحي أكثر إذا احتجتِ</span></div><div class="actions-row"><span id="restCounter" class="timer-num num">${restSeconds}</span><button class="btn secondary small" data-action="timer-toggle">${restInterval?'إيقاف':'ابدئي'}</button><button class="btn outline small" data-action="timer-reset">إعادة</button></div></div><div class="soft-rule"></div><div class="actions-row"><button class="btn primary" data-action="finish-workout" ${finished?'disabled':''}>${I('award')} ${finished?'أكملتيها!':'أنهيت جلستي ✨'}</button><button class="btn outline" data-action="open-habit">سجّلي شعورك اليوم</button></div><p class="subtle">ينفع تكتفين ببعض التمارين أو تكرارات أقل. الفيديو يشرح الحركة؛ لا تقلدي شدته أو جرعاته.</p></section>
<section class="grid two" style="margin-top:18px"><article class="card"><div class="card-header"><h2>متى أتدرج؟</h2><span class="tag outline">مرن</span></div><p class="muted">${esc(pro.increaseIf||'عندما تتمكنين من الحركة الصحيحة براحة خلال أكثر من حصة')}</p><div class="soft-rule"></div><div class="metric-row"><span class="subtle">إذا زاد الانزعاج</span></div><p class="muted">${esc(pro.deloadIf||'خففي المستوى وتواصلي مع الطبيبة عند ظهور أعراض جديدة')}</p></article><article class="card"><div class="card-header"><h2>روتينك الأسبوعي</h2></div><div class="summary-day"><span class="tag">A</span><div><strong>جلسة جسم كامل</strong><span>مثل الاثنين — حسب جدولك</span></div></div><div style="height:8px"></div><div class="summary-day"><span class="tag">B</span><div><strong>جلسة متنوعة</strong><span>بعد راحة مناسبة — مثل الخميس</span></div></div><p class="subtle">أيام الأسبوع أمثلة، ويمكنك نقل الجلسات وفق تعافيك.</p></article></section>
<section class="card" style="margin-top:18px"><div class="card-header"><div><h2>مكتبة فيديوهاتك الكاملة</h2><span class="card-sub">12 حركة للبداية، و19 حركة مرجعية، و7 حركات علاجية مشروطة</span></div><span class="tag">YouTube</span></div>
<details><summary style="cursor:pointer;font-weight:800;padding:10px 0;color:var(--brand)">افتحي ${DATA.videoLibrary?.length||0} بطاقة فيديو وشرح مطابقة المصدر</summary><div class="alert warn" style="margin:12px 0">${I('info')}<div>استخدمي فيديوهات جلسات A وB فقط لخطتك الحالية. التمارين EX مرجعية وغير نشطة؛ تمارين PT تنتظر وصفًا علاجيًا محددًا. الفيديو للتعليم وليس لتحديد التكرارات.</div></div><div class="recipe-grid">${(DATA.videoLibrary||[]).map(v=>`<article class="recipe"><div class="recipe-meta"><span class="tag ${v.status==='active'?'good':v.status==='conditional'?'warn':'outline'}">${v.status==='active'?'برنامج البداية':v.status==='conditional'?'علاج طبيعي مشروط':'مرحلة لاحقة'}</span><span class="subtle">${esc(v.id)}</span></div><h3>${esc(v.name)}</h3><p class="subtle">${esc(v.source)} · ${esc(v.match)}</p><p class="subtle">${esc(v.note)}</p>${v.video?`<a href="${esc(v.video)}" target="_blank" rel="noopener noreferrer" class="btn secondary small">${I('play')} فيديو يوتيوب</a>`:'<span class="tag warn">لا يوجد فيديو مطابق</span>'}</article>`).join('')}</div></details></section>`}
function foodView(){const t=targets(),sum=nutrientTotal(),meals=todayMeals(),d=today(),filtered=DATA.recipes.filter(r=>!r.peanutRisk&&(!recipeCategory||recipeCategory==='الكل'||r.category===recipeCategory)&&(!recipeSearch||r.name.includes(recipeSearch))),categories=[...new Set(DATA.recipes.map(r=>r.category))].filter(Boolean);return `${pageHeader('أكلك، بدون تعقيد','وجبتان رئيسيتان وسناك اختياري — التزام مرن بلا حرمان أو قواعد قاسية.','FUEL YOUR BODY')}
<section class="alert" style="margin-bottom:16px">${I('info')}<div>الأهداف الغذائية هنا <strong>تجريبية وغير معتمدة طبيًا</strong>. تدوير الكربوهيدرات خيار للتنظيم وليس شرطًا للنزول. الأهم إجمالي الطعام المناسب، الشبع والاستمرارية. استبعدنا الوصفات المعروفة بالفول السوداني؛ لم تتحقق مكونات الوصفات الأخرى من جوز الهند.</div></section>
<section class="grid two"><article class="card"><div class="card-header"><h2>نوع اليوم</h2><span class="tag outline">اختيارك</span></div><div class="pills" style="margin-bottom:16px"><button class="pill ${foodType()==='high'?'active':''}" data-food-mode="high">أعلى كارب</button><button class="pill ${foodType()==='medium'?'active':''}" data-food-mode="medium">متوسط كارب</button></div><div class="metric-row"><span class="subtle">الهدف التجريبي لليوم</span><strong style="font-size:25px"><span class="num">${fmt(t.cal)}</span> <small>سعرة</small></strong></div><div class="soft-rule"></div><div class="metric-row"><span class="subtle">بروتين</span><strong>${fmt(t.p)} جم</strong></div><div class="metric-row"><span class="subtle">كربوهيدرات</span><strong>${fmt(t.c)} جم</strong></div><div class="metric-row"><span class="subtle">دهون</span><strong>${fmt(t.f)} جم</strong></div></article><article class="card"><div class="card-header"><h2>المسجّل اليوم</h2><span class="tag">${fmt(meals.length)} مدخلات</span></div><div style="font-size:34px;font-weight:900"><span class="num">${fmt(sum.cal)}</span> <small style="font-size:13px;color:var(--muted)">سعرة مسجلة</small></div><div class="progress" style="margin:10px 0"><i style="width:${t.cal?Math.min(100,sum.cal/t.cal*100):0}%"></i></div><div class="metric-row"><span class="subtle">بروتين</span><strong>${fmt(sum.protein,1)} / ${fmt(t.p)} جم</strong></div><div class="metric-row"><span class="subtle">كارب</span><strong>${fmt(sum.carbs,1)} / ${fmt(t.c)} جم</strong></div><div class="metric-row"><span class="subtle">دهون</span><strong>${fmt(sum.fat,1)} / ${fmt(t.f)} جم</strong></div><div class="soft-rule"></div><button class="btn primary small" data-action="open-meal">${I('add')} إضافة وجبة</button><p class="subtle">الأرقام تعتمد على ما تدخلينه، ولا تعني أن القيم الفعلية تحققت.</p></article></section>
<section class="grid two" style="margin-top:18px;align-items:start"><article class="card"><div class="card-header"><h2>وجباتك اليوم</h2><span class="tag outline">وجبتان + اختياري</span></div>${meals.length?meals.map(m=>`<div class="entry"><div class="entry-main"><strong>${esc(m.name)}</strong><span>${esc(m.slot)} · ${fmt(m.protein,1)} جم بروتين</span></div><div class="entry-actions"><b class="num">${fmt(m.cal)}</b><button class="icon-button" style="width:32px;height:32px" title="حذف الوجبة" aria-label="حذف الوجبة" data-action="delete-meal" data-id="${esc(m.id)}">${I('trash')}</button></div></div>`).join(''):`<div class="empty"><div class="empty-art">◌</div>لسّه ما سجلتي وجبات. اكتبي أول وجبة، وبس.</div>`}<div style="margin-top:14px"><button class="btn secondary small" data-action="open-meal">تسجيل وجبة ${I('add')}</button></div></article><article class="card"><div class="card-header"><h2>وجبتان تناسبان يومك</h2><span class="tag">أفكار مرنة</span></div>${DATA.mealIdeas.filter(x=>x.type===t.type).slice(0,3).map(x=>`<div class="summary-day" style="margin-bottom:9px"><div class="medal">${x.meal.includes('1')?'١':'٢'}</div><div><strong>${esc(x.name)}</strong><span>${esc(x.protein)} + ${esc(x.carb)}</span></div></div>`).join('')}<p class="subtle">تقدير السعرات يحتاج كميات حقيقية. ما فيه أكل «ممنوع» إلا ما يمسّ حساسيتك.</p></article></section>
<section class="card" style="margin-top:18px"><div class="card-header"><div><h2>مكتبة وصفاتك · ${fmt(DATA.recipes.length)} وصفة</h2><span class="card-sub">مستوردة من Life OS — السعرات تقديرية وليست قياسات موثقة</span></div><span class="tag warn">حساسية</span></div><div class="form-row" style="margin-bottom:16px"><label class="field">ابحثي عن وصفة<input id="recipeSearch" type="search" value="${esc(recipeSearch)}" placeholder="شوفان، دجاج، تونة..." /></label><label class="field" style="max-width:180px">التصنيف<select id="recipeCategory"><option>الكل</option>${categories.map(c=>`<option value="${esc(c)}" ${c===recipeCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div id="recipeResults" class="recipe-grid">${recipesHtml(filtered)}</div><p class="subtle">الوصفات الأربع المحتوية على فول سوداني مخفية. غياب علامة التحذير لا يثبت خلو الوصفة من جوز الهند أو أثر المكسرات؛ افحصي المكونات بنفسك.</p></section>`}
function recipesHtml(list){return list.slice(0,24).map(r=>`<article class="recipe"><div class="recipe-meta"><span class="tag outline">${esc(r.category)}</span><span class="subtle"><span class="num">${fmt(r.estimatedCalories)}</span> سعرة تقديرية</span></div><h3>${esc(r.name)}</h3><div class="recipe-meta"><span class="subtle">مكونات غير متحقق منها</span><button class="btn-plain" data-action="recipe-to-meal" data-id="${esc(r.id)}">اختاريها ${I('add')}</button></div></article>`).join('')||'<div class="empty">ما لقينا وصفات بهذا البحث.</div>'}
function progressView(){const weight=lastWeight(),loss=Math.max(0,n(state.settings.startWeight)-weight),progress=progressPct(),weights=state.weights.slice().sort((a,b)=>a.date.localeCompare(b.date)),act=activityDates().size,days=activeWeekDays(),hab=state.habits[today()]||{},completed=workoutFinished();return `${pageHeader('تقدّمك يستاهل الاحتفال','نقيس التقدم بإنجازاتك وصحتك وقوتك، مو برقم الميزان وحده.','YOUR JOURNEY')}
<section class="grid four"><article class="card kpi"><div class="label">وزنك الحالي</div><div class="big"><span class="num">${fmt(weight,1)}</span> <small>كجم</small></div></article><article class="card kpi"><div class="label">التغير من البداية</div><div class="big"><span class="num">${fmt(loss,1)}</span> <small>كجم</small></div></article><article class="card kpi"><div class="label">إكمال حصص المقاومة</div><div class="big">${fmt(completed)} <small>حصة</small></div></article><article class="card kpi"><div class="label">أيام المتابعة</div><div class="big">${fmt(act)} <small>يوم</small></div></article></section>
<section class="grid two" style="margin-top:19px;align-items:start"><article class="card"><div class="card-header"><h2>تطور الوزن</h2><span class="tag outline">من ${fmt(state.settings.startWeight)} إلى ${fmt(state.settings.targetWeight)}</span></div>${weightChart(weights)}<div class="soft-rule"></div><form id="weightForm"><div class="form-row"><label class="field">التاريخ<input type="date" name="date" required value="${today()}"/></label><label class="field">الوزن (كجم)<input type="number" name="kg" min="25" max="350" step="0.1" required placeholder="مثال: 79.5"/></label><button class="btn primary" type="submit">حفظ</button></div></form><p class="subtle">سجّلي وزنك عند رغبتك، ويفضل في ظروف قياس متشابهة. التذبذب اليومي طبيعي.</p></article>
<article class="card"><div class="card-header"><h2>رعاية جسمك اليوم</h2><span class="tag outline">الراحة إنجاز</span></div><form id="habitForm"><div class="form-grid"><label class="field">مشي مريح (دقيقة)<input type="number" name="walk" min="0" max="600" step="1" value="${n(hab.walk)}" /></label><label class="field">النوم (ساعة)<input type="number" name="sleep" min="0" max="24" step="0.5" value="${n(hab.sleep)}" /></label><label class="field">أكواب ماء (اختياري)<input type="number" name="water" min="0" max="40" step="1" value="${n(hab.water)}" /></label><label class="field">طاقة اليوم<select name="energy">${[['','بدون تقييم'],['1','قليلة جدًا'],['2','قليلة'],['3','متوسطة'],['4','جيدة'],['5','ممتازة']].map(([v,l])=>`<option value="${v}" ${String(hab.energy||'')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="field" style="margin-top:12px">ملاحظة لجسمك أو مزاجك<textarea name="note" placeholder="كيف كان جسمك اليوم؟ هل احتجتِ راحة؟">${esc(hab.note||'')}</textarea></label><div class="actions-row" style="margin-top:12px"><button class="btn primary" type="submit">${I('heart')} حفظ اليوم</button><span class="subtle">ما فيه هدف ماء أو مشي مفروض عليك</span></div></form></article></section>
<section class="card" style="margin-top:19px"><div class="card-header"><div><h2>المكافآت الصغيرة ✳</h2><span class="card-sub">نحتفل بالاهتمام بنفسك، حتى لو كانت الأيام متقطعة</span></div><span class="tag good">${rewards().filter(x=>x.ok).length} / ${rewards().length}</span></div><div class="badge-grid">${rewards().map(r=>`<div class="achievement ${r.ok?'':'off'}"><div class="medal">${r.icon}</div><div><strong>${r.name} ${r.ok?'✓':''}</strong><small>${r.ok?'فتحتِ الوسام!':r.description}</small></div></div>`).join('')}</div></section>
<section class="card" style="margin-top:19px"><div class="card-header"><h2>سجل الميزان</h2><span class="tag outline">اختياري تمامًا</span></div>${weights.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الوزن</th><th>التحكم</th></tr></thead><tbody>${weights.slice().reverse().map(x=>`<tr><td>${esc(x.date)}</td><td><span class="num">${fmt(x.kg,1)}</span> كجم</td><td><button class="btn-plain" data-action="delete-weight" data-date="${esc(x.date)}">حذف</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا توجد قياسات فعلية مسجلة بعد. البداية 80 كجم من خطتك الأساسية.</div>'}</section>`}
function weightChart(weights){let pts=[{date:state.settings.startDate,kg:n(state.settings.startWeight)},...weights.map(x=>({date:x.date,kg:n(x.kg)}))].sort((a,b)=>a.date.localeCompare(b.date));const uniqueByDate=new Map();pts.forEach(x=>uniqueByDate.set(x.date,x));pts=Array.from(uniqueByDate.values());let vals=pts.map(x=>x.kg);let low=Math.min(n(state.settings.targetWeight),...vals)-1,high=Math.max(n(state.settings.startWeight),...vals)+1;if(high-low<4)high=low+4;const w=560,h=210,l=30,r=18,t=15,b=32;function coord(p,i){return [l+(pts.length===1?.5:i/(pts.length-1))*(w-l-r),t+(high-p.kg)/(high-low)*(h-t-b)]}let lines=pts.map(coord),path=lines.map((x,i)=>(i?'L':'M')+x[0].toFixed(1)+' '+x[1].toFixed(1)).join(' '),area=path+` L${lines.at(-1)[0].toFixed(1)} ${h-b} L${lines[0][0].toFixed(1)} ${h-b} Z`;return `<div class="chart-wrap"><svg class="linechart" viewBox="0 0 ${w} ${h}" role="img" aria-label="منحنى سجل الوزن"><line class="gridline" x1="${l}" x2="${w-r}" y1="${t}" y2="${t}"/><line class="gridline" x1="${l}" x2="${w-r}" y1="${(h-b+t)/2}" y2="${(h-b+t)/2}"/><line class="gridline" x1="${l}" x2="${w-r}" y1="${h-b}" y2="${h-b}"/><text x="${l}" y="${t+13}">${fmt(high,1)}</text><text x="${l}" y="${h-b-8}">${fmt(low,1)}</text><path class="area" d="${area}"/><path class="trend" d="${path}"/>${lines.map(([x,y])=>`<circle class="dot" cx="${x}" cy="${y}" r="5"/>`).join('')}<text x="${l}" y="${h-6}">${esc(pts[0].date)}</text>${pts.length>1?`<text x="${w-100}" y="${h-6}">${esc(pts.at(-1).date)}</text>`:''}</svg></div>`}
function moreView(){const s=state.settings;const bmr=Math.round(10*n(state.settings.startWeight)+6.25*n(state.settings.height)-5*n(state.settings.age)-161),tdee=Math.round(bmr*1.2);return `${pageHeader('كل شيء تحت سيطرتك','الملف والخصوصية والتخصيص — مساحتك ملكك.','YOUR SPACE')}
<section class="grid two" style="align-items:start"><article class="card"><div class="card-header"><h2>ملفك وأهدافك</h2><span class="tag">قابل للتعديل</span></div><form id="settingsForm"><div class="form-grid"><label class="field">الوزن المرجعي (كجم)<input type="number" name="startWeight" min="25" max="350" step=".1" value="${esc(s.startWeight)}" required></label><label class="field">وزن الهدف (كجم)<input type="number" name="targetWeight" min="25" max="350" step=".1" value="${esc(s.targetWeight)}" required></label><label class="field">الطول (سم)<input type="number" name="height" min="100" max="230" step="1" value="${esc(s.height)}" required></label><label class="field">العمر (سنة)<input type="number" name="age" min="15" max="100" step="1" value="${esc(s.age)}" required></label><label class="field">بداية الخطة<input type="date" name="startDate" value="${esc(s.startDate)}" required></label><label class="field">النمط الافتراضي<label style="font-weight:500;color:var(--muted)">يُحدَّد تلقائيًا من اليوم، ويمكن تغييره في التغذية</label></label></div><div class="soft-rule"></div><h3>أهداف التغذية التجريبية</h3><div class="form-grid"><label class="field">أعلى كارب (سعرة)<input type="number" name="goalHigh" min="800" max="4500" step="10" value="${esc(s.goalHigh)}"></label><label class="field">متوسط كارب (سعرة)<input type="number" name="goalMedium" min="800" max="4500" step="10" value="${esc(s.goalMedium)}"></label><label class="field">بروتين يومي (جم)<input type="number" name="protein" min="0" max="300" step="5" value="${esc(s.protein)}"></label><label class="field">كارب أعلى (جم)<input type="number" name="carbHigh" min="0" max="600" step="5" value="${esc(s.carbHigh)}"></label><label class="field">كارب متوسط (جم)<input type="number" name="carbMedium" min="0" max="600" step="5" value="${esc(s.carbMedium)}"></label><label class="field">دهون يوم أعلى (جم)<input type="number" name="fatHigh" min="0" max="300" step="5" value="${esc(s.fatHigh)}"></label><label class="field">دهون يوم متوسط (جم)<input type="number" name="fatMedium" min="0" max="300" step="5" value="${esc(s.fatMedium)}"></label></div><p class="subtle">قد لا تتطابق الماكروز مع السعرات بعد تغيير أحد الأرقام. لا تُعتبر هذه الحاسبة خطة علاجية أو قياسًا مخبريًا.</p><button class="btn primary" type="submit">حفظ التفضيلات</button></form></article>
<article class="grid" style="gap:18px"><div class="card"><div class="card-header"><h2>ثبّتي التطبيق على جوالك</h2><span class="tag good">PWA</span></div><p class="muted">افتحيه من الأيقونة على الشاشة الرئيسية وسجّلي «أنجزت»؛ سجلاتك تُحفظ على جهازك تلقائيًا. لا توجد مزامنة مع الكمبيوتر.</p><button class="btn secondary" data-action="install-help">طريقة التثبيت على جوالي</button></div><div class="card"><div class="card-header"><h2>احتياجك التقديري للطاقة</h2><span class="tag outline">معادلة تقديرية</span></div><div class="grid two" style="gap:10px"><div><span class="subtle">الراحة BMR</span><div class="big" style="font-size:28px;font-weight:900">${fmt(bmr)} <small style="font-size:11px">سعرة</small></div></div><div><span class="subtle">يوم قليل النشاط TDEE</span><div class="big" style="font-size:28px;font-weight:900">${fmt(tdee)} <small style="font-size:11px">سعرة</small></div></div></div><p class="subtle">حساب Mifflin–St Jeor للمرأة × معامل 1.2، وليس قياسًا فعليًا أو توصية بحمية. يتغير حسب النشاط والبيانات. <a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">مصدر المعادلة</a></p></div><div class="card"><div class="card-header"><h2>التحفيز اللي يناسبك</h2><span class="tag good">بدون ضغط</span></div><div class="quote-card"><span class="quote-caption">WEJDAN REMINDER</span><blockquote>أنتِ أهم من قائمة المهام.</blockquote></div><p class="subtle">الأوسمة تُمنح للاستمرارية والاهتمام بالنفس، لا لتقليل الطعام أو إكمال تمرين مؤلم. ما فيه عقاب أو إعادة ضبط لعدد أيام متتالية.</p></div><div class="card"><div class="card-header"><h2>بياناتك وخصوصيتك</h2></div><p class="muted">كل ما تدخلينه محفوظ محليًا في هذا المتصفح على هذا الجهاز. ما فيه حساب ولا مزامنة سحابية. احفظي نسخة احتياطية إذا بتغيّرين الجهاز أو المتصفح.</p><div class="actions-row"><button class="btn primary" data-action="export">${I('download')} تصدير JSON</button><button class="btn outline" data-action="import">${I('upload')} استيراد نسخة</button></div><input id="importPicker" type="file" accept="application/json,.json" hidden><div class="soft-rule"></div><button class="btn danger small" data-action="reset-data">حذف سجلاتي المحلية</button></div><div class="card"><div class="card-header"><h2>الهوية والمصادر</h2></div><p class="muted">ألوان النسختين الفاتحة والداكنة مأخوذة من <strong>Wejdan — Color</strong> في ملف هويتك بفِقما. الخطوط المرجعية: ثمانية للعناوين وIBM Plex Sans للنصوص، مع بدائل نظامية عند عدم تثبيتها.</p><div class="pills"><span class="tag">#6172B5</span><span class="tag">#9BC4EE</span><span class="tag outline">Light + Dark</span></div><div class="soft-rule"></div><a href="https://www.figma.com/design/pei6kBFtNKDcYAwPBG1gTN/" target="_blank" rel="noopener noreferrer">ملف الهوية الأصلي في Figma ↗</a><div class="soft-rule"></div>${DATA.sources.map(x=>`<p style="margin:6px 0;font-size:12px"><a target="_blank" rel="noopener noreferrer" href="${esc(x.url)}">${esc(x.title)} ↗</a></p>`).join('')}</div></article></section>`}
function openModal(title,body){closeModal();const modal=document.getElementById('modalRoot');modal.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="إغلاق">${I('close')}</button></div>${body}</div></div>`;document.body.style.overflow='hidden';modal.querySelector('.icon-button')?.focus()}
function closeModal(){document.getElementById('modalRoot').innerHTML='';document.body.style.overflow=''}
function exerciseDetails(id){const x=DATA.exercises.find(x=>x.id===id);if(!x)return;const url=x.video&&/^https:\/\/www\.youtube\.com\//.test(x.video)?x.video:null;openModal(x.name,`<div class="pills" style="margin-bottom:10px"><span class="tag">جلسة ${esc(x.session)}</span><span class="tag outline">${esc(x.reps)} تكرار</span><span class="tag outline">${esc(x.rest)} راحة</span></div><div class="modal-section"><h4>١ — الاستعداد</h4><p>${esc(x.start)}</p></div><div class="modal-section"><h4>٢ — التنفيذ</h4><p>${esc(x.steps)}</p></div><div class="modal-section"><h4>٣ — احمي رقبتك وظهرك</h4><p>${esc(x.protect)}</p></div><div class="modal-section"><h4>التنفس</h4><p>${esc(x.breathing)}</p></div><div class="modal-section"><h4>إذا صعُب عليك</h4><p>${esc(x.easier)}</p></div><div class="alert warn" style="margin:14px 0">${I('warning')}<div>أوقفي الحركة عند: ${esc(x.stop)}. أي تعليمات خاصة من طبيبتك مقدّمة على الفيديو.</div></div>${url?`<a class="btn primary block" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${I('play')} شاهدي الفيديو على YouTube</a>`:'<p class="warning">لا يتوفر فيديو مطابق موثوق لهذه الحركة.</p>'}<p class="subtle" style="margin-top:10px">المصدر: ${esc(x.videoSource||'تعليمي')} · المطابقة: ${esc(x.videoQuality||'راجعِي الوصف')}</p>`)}
function mealModal(prefill=null){const recipe=prefill?DATA.recipes.find(x=>x.id===prefill):null;openModal('سجّلي وجبتك',`<p class="muted" style="margin-top:0">وجبتان رئيسيتان + سناك اختياري. أدخلي القيم من الحصص والملصقات الغذائية.</p>${recipe?`<div class="alert warn" style="margin-bottom:13px">${I('info')}<div>وصفة «${esc(recipe.name)}» تُقدّر بـ${fmt(recipe.estimatedCalories)} سعرة، لكن مكوّناتها وحجم حصتها <strong>غير متحقق منهما</strong>. افحصي الحساسية، ثم أدخلي القيم الصحيحة بنفسك.</div></div>`:''}<form id="mealForm"><div class="form-grid"><label class="field">التاريخ<input type="date" name="date" value="${today()}" required></label><label class="field">نوع الوجبة<select name="slot"><option>وجبة 1</option><option>وجبة 2</option><option>سناك اختياري</option></select></label></div><label class="field" style="margin-top:12px">اسم الأكل<input type="text" name="name" required maxlength="100" value="${esc(recipe?.name||'')}" placeholder="مثال: أرز ودجاج وخضار"></label><div class="form-grid" style="margin-top:12px"><label class="field">السعرات (kcal)<input type="number" name="cal" required min="0" max="4000" step="1" placeholder="من مجموع المكونات"></label><label class="field">البروتين (جم)<input type="number" name="protein" min="0" max="300" step=".1" placeholder="اختياري"></label><label class="field">الكارب (جم)<input type="number" name="carbs" min="0" max="600" step=".1" placeholder="اختياري"></label><label class="field">الدهون (جم)<input type="number" name="fat" min="0" max="300" step=".1" placeholder="اختياري"></label></div><p class="subtle">بسبب حساسية الفول السوداني وجوز الهند: راجعي المكونات وآثار التلوث المتبادل قبل الأكل.</p><button class="btn primary block" type="submit">حفظ الوجبة</button></form>`)}
function habitModal(){const h=state.habits[today()]||{};openModal('كيف كان جسمك اليوم؟',`<form id="habitForm"><div class="form-grid"><label class="field">مشي مريح (دقيقة)<input type="number" name="walk" min="0" max="600" step="1" value="${n(h.walk)}"></label><label class="field">ساعات النوم<input type="number" name="sleep" min="0" max="24" step="0.5" value="${n(h.sleep)}"></label><label class="field">ماء (أكواب اختيارية)<input type="number" name="water" min="0" max="40" step="1" value="${n(h.water)}"></label><label class="field">طاقة اليوم<select name="energy">${[['','بدون تقييم'],['1','منخفضة جدًا'],['2','منخفضة'],['3','عادية'],['4','جيدة'],['5','عالية']].map(([v,l])=>`<option value="${v}" ${String(h.energy||'')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="field" style="margin-top:12px">ملاحظة لطيفة<textarea name="note">${esc(h.note||'')}</textarea></label><button class="btn primary block" style="margin-top:12px" type="submit">حفظ يومي ✳</button></form>`)}
function recordWorkout(){const key=workoutKey(),e=workoutState(),ex=DATA.exercises.filter(x=>x.session===selectedSession),total=ex.reduce((s,x)=>s+(e.sets?.[x.id]||[]).filter(Boolean).length,0);if(!total){toast('أنجزي مجموعة واحدة على الأقل أو خذي راحة اليوم؛ الخيار لك.');return}if(e.finished)return;state.workouts[key]={...e,finished:true,finishedAt:new Date().toISOString(),session:selectedSession,date:today()};if(!save())return;confetti();toast('يا سلام عليك! اكتملت الجلسة وانحفظت على جوالك ✓ ✨');render(true)}
function timerAction(action){const counter=document.getElementById('restCounter');if(action==='timer-reset'){clearInterval(restInterval);restInterval=null;restSeconds=60;render(true);return}if(restInterval){clearInterval(restInterval);restInterval=null;render(true);return}if(restSeconds<=0)restSeconds=60;restInterval=setInterval(()=>{restSeconds--;const c=document.getElementById('restCounter');if(c)c.textContent=String(restSeconds);if(restSeconds<=0){clearInterval(restInterval);restInterval=null;toast('انتهت الراحة، وخذي وقتك لو تحتاجين أكثر 🤍');render(true)}},1000);render(true)}
function exportJSON(){const doc={app:'WEJDAN FIT',exportedAt:new Date().toISOString(),data:state};const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`WEJDAN_FIT_backup_${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast('تم تجهيز النسخة الاحتياطية')}
function importJSON(file){const reader=new FileReader();reader.onload=()=>{try{const obj=JSON.parse(reader.result);const dat=obj.data||obj;if(!dat.settings||!Array.isArray(dat.weights)||!Array.isArray(dat.meals)||typeof dat.workouts!=='object')throw Error('format');if(!confirm('استيراد النسخة سيستبدل بياناتك الحالية في هذا المتصفح. متأكدة؟'))return;state={...deep(BASE),...dat,settings:{...deep(BASE.settings),...dat.settings}};save();render();toast('استعدنا بياناتك من النسخة الاحتياطية ✓')}catch(e){toast('هذا الملف ليس نسخة احتياطية صحيحة من WEJDAN FIT')}};reader.readAsText(file)}
// Actions
function installHelp(){const ios=/iPhone|iPad|iPod/.test(navigator.userAgent);openModal('خلي WEJDAN FIT على شاشة جوالك',`<p class="muted">${ios?'على الآيفون: افتحي رابط التطبيق عبر Safari، اضغطي زر المشاركة، ثم «إضافة إلى الشاشة الرئيسية / Add to Home Screen». فعّلي خيار «فتح كتطبيق ويب» عند ظهوره.':'على أندرويد: افتحي الرابط في Chrome، واختاري «تثبيت التطبيق» من القائمة ⋮ أو من نافذة التثبيت إذا ظهرت.'}</p><div class="alert warn">${I('info')}<div>إنجازاتك تنحفظ محليًا على نفس الجوال والمتصفح. GitHub لا يستقبل سجلاتك، ولا توجد مزامنة بين الأجهزة. صدّري نسخة احتياطية من «المزيد» كل فترة ولا تفتحي التطبيق في وضع خاص.</div></div>${deferredInstallPrompt?'<button class="btn primary block" data-action="install-native">تثبيت التطبيق الآن</button>':''}`)}
function onboard(){openModal('جهّزي مساحتك الخاصة',`<p class="muted">مرة واحدة فقط على جوالك. معلوماتك تُحفظ على الجهاز، وليست داخل ملفات GitHub العامة.</p><form id="setupForm"><div class="form-grid"><label class="field">وزنك الحالي (كجم)<input name="startWeight" type="number" min="25" max="350" step="0.1" required placeholder="مثال: 70"></label><label class="field">هدفك (كجم)<input name="targetWeight" type="number" min="25" max="350" step="0.1" required placeholder="مثال: 65"></label><label class="field">الطول (سم)<input name="height" type="number" min="100" max="230" required placeholder="مثال: 165"></label><label class="field">العمر (سنة)<input name="age" type="number" min="18" max="100" required placeholder="مثال: 25"></label></div><p class="subtle">أهداف السعرات المعروضة لاحقًا أمثلة تجريبية؛ عدّليها بعد مراجعة احتياجك.</p><button type="submit" class="btn primary block">احفظي بياناتي على جوالي ♡</button></form>`)}
function handleClick(e){if(e.target.classList?.contains('modal-backdrop')){if(state.settings.setupComplete)closeModal();return}const actionTarget=e.target.closest('[data-action]');const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return}const foodMode=e.target.closest('[data-food-mode]');if(foodMode){state.foodModes[today()]=foodMode.dataset.foodMode;save();render(true);return}const sess=e.target.closest('[data-session]');if(sess){selectedSession=sess.dataset.session;render(true);return}if(!actionTarget)return;const a=actionTarget.dataset.action;if(a==='close-modal'){if(state.settings.setupComplete)closeModal();return}if(a==='install-help'){installHelp();return}if(a==='install-native'){if(deferredInstallPrompt){deferredInstallPrompt.prompt();deferredInstallPrompt=null;closeModal()}return}if(a==='exercise-details'){exerciseDetails(actionTarget.dataset.exercise);return}if(a==='toggle-set'){const id=actionTarget.dataset.exercise,idx=n(actionTarget.dataset.set),key=workoutKey(),w=workoutState();if(w.finished){toast('هذه الحصة مكتملة؛ اختاري يومًا جديدًا للتسجيل.');return}w.sets=w.sets||{};const arr=w.sets[id]||[];arr[idx]=!arr[idx];w.sets[id]=arr;state.workouts[key]=w;save();render(true);return}if(a==='finish-workout'){recordWorkout();return}if(a==='timer-toggle'||a==='timer-reset'){timerAction(a);return}if(a==='open-meal'){mealModal();return}if(a==='recipe-to-meal'){const r=DATA.recipes.find(r=>r.id===actionTarget.dataset.id);if(r?.peanutRisk){toast('هذه الوصفة تحتوي على فول سوداني، ولم تُضف.');return}mealModal(actionTarget.dataset.id);return}if(a==='open-habit'){habitModal();return}if(a==='delete-meal'){if(!confirm('حذف هذه الوجبة من السجل؟'))return;state.meals=state.meals.filter(x=>x.id!==actionTarget.dataset.id);save();render(true);toast('حُذفت الوجبة');return}if(a==='delete-weight'){if(!confirm('حذف هذا الوزن المسجل؟'))return;state.weights=state.weights.filter(x=>x.date!==actionTarget.dataset.date);save();render(true);return}if(a==='export'){exportJSON();return}if(a==='import'){document.getElementById('importPicker')?.click();return}if(a==='reset-data'){if(confirm('هذا سيحذف جميع سجلاتك المحلية بعد آخر نسخة احتياطية. متأكدة؟')){if(confirm('تأكيد أخير: حذف سجلات WEJDAN FIT؟')){state=deep(BASE);save();render();toast('أعيدت المساحة إلى البداية')}}return}}
function handleSubmit(e){const form=e.target;if(!['mealForm','weightForm','habitForm','settingsForm','setupForm'].includes(form.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(form).entries());if(form.id==='setupForm'){for(const k of ['startWeight','targetWeight','height','age']){state.settings[k]=Number(d[k]);if(!Number.isFinite(state.settings[k])||state.settings[k]<=0){toast('أدخلي معلومات صحيحة');return}}state.settings.startDate=today();state.settings.setupComplete=true;if(!save())return;closeModal();render();toast('حفظنا معلوماتك محليًا على هذا الجهاز ✓');return}if(form.id==='mealForm'){if(!d.name.trim()||!d.date||!Number.isFinite(Number(d.cal))||d.cal===''){toast('اكتبي اسم الوجبة والسعرات الفعلية لتسجيلها.');return}let entry={id:'meal_'+Date.now()+'_'+Math.floor(Math.random()*9999),date:d.date,slot:d.slot,name:d.name.trim().slice(0,100),cal:n(d.cal),protein:n(d.protein),carbs:n(d.carbs),fat:n(d.fat)};state.meals.push(entry);if(!save())return;closeModal();render(true);toast('انحفظت وجبتك، بالعافية ♡');return}if(form.id==='weightForm'){let kg=n(d.kg);if(!d.date||kg<25||kg>350){toast('تأكدي من التاريخ والوزن.');return}state.weights=state.weights.filter(x=>x.date!==d.date);state.weights.push({date:d.date,kg});if(!save())return;confetti();render(true);toast('سجّلنا القياس، وشكرًا لاهتمامك بنفسك');return}if(form.id==='habitForm'){const current=state.habits[today()]||{};state.habits[today()]={...current,walk:Math.min(600,Math.max(0,n(d.walk))),sleep:Math.min(24,Math.max(0,n(d.sleep))),water:Math.min(40,Math.max(0,n(d.water))),energy:d.energy||'',note:String(d.note||'').slice(0,600)};if(!save())return;closeModal();render(true);toast('شكراً إنك اعتنيتِ بيومك ♡');return}if(form.id==='settingsForm'){for(const k of ['startWeight','targetWeight','height','age','goalHigh','goalMedium','protein','carbHigh','carbMedium','fatHigh','fatMedium'])state.settings[k]=n(d[k]);state.settings.startDate=d.startDate||state.settings.startDate;if(!save())return;render(true);toast('تفضيلاتك انحفظت');return}}
function handleChange(e){if(e.target.id==='setLevel'){state.settings.trainingSets=Math.max(1,Math.min(3,n(e.target.value)));save();render(true)}if(e.target.id==='recipeCategory'){recipeCategory=e.target.value;recipeSearch=document.getElementById('recipeSearch')?.value.trim()||'';render(true)}if(e.target.id==='importPicker'&&e.target.files?.length)importJSON(e.target.files[0])}
function handleInput(e){if(e.target.id==='recipeSearch'){recipeSearch=e.target.value.trim();const list=DATA.recipes.filter(r=>!r.peanutRisk&&(recipeCategory==='الكل'||r.category===recipeCategory)&&r.name.includes(recipeSearch));document.getElementById('recipeResults').innerHTML=recipesHtml(list)}}
function init(){window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e});document.getElementById('installHelpBtn')?.addEventListener('click',installHelp);document.getElementById('themeSwitch').addEventListener('click',()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render(true)});document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.settings.setupComplete)closeModal()});render();save();if(!state.settings.setupComplete)onboard();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init();
})();
